#!/usr/bin/env bash
set -euo pipefail

cd "$(dirname "$0")/.."

BIN="${BIN:-./nfield}"
TIMEOUT_SECONDS="${TIMEOUT_SECONDS:-10}"
COMMAND_DOC_ROOT="${COMMAND_DOC_ROOT:-}"

tests_run=0
tests_passed=0
tests_failed=0

fail() {
    tests_failed=$((tests_failed + 1))
    printf '  FAIL: %s\n' "$1"
}

pass() {
    tests_passed=$((tests_passed + 1))
}

run_capture() {
    local cmd="$1"
    local outfile="$2"
    local errfile="$3"
    local timeout_seconds="$TIMEOUT_SECONDS"

    case "$cmd" in
        finite-character-pairing* \
        | verify\ finite-character-pairing \
        | natural-prime-sum-window* \
        | verify\ natural-prime-sum-window \
        | collision-transform* \
        | verify\ collision-transform \
        | finite-determination* \
        | verify\ finite-determination \
        | finite-spectral-quotient* \
        | verify\ finite-spectral-quotient \
        | collision-spectrum-factorization* \
        | verify\ collision-spectrum-factorization \
        | special-value-moment* \
        | verify\ special-value-moment \
        | short-sum-bernoulli-correlation* \
        | verify\ short-sum-bernoulli-correlation)
            timeout_seconds=60
            ;;
    esac

    timeout "$timeout_seconds" "$BIN" $cmd >"$outfile" 2>"$errfile"
}

assert_command_contains() {
    local cmd="$1"
    shift
    local out err
    out="$(mktemp)"
    err="$(mktemp)"
    tests_run=$((tests_run + 1))

    if ! run_capture "$cmd" "$out" "$err"; then
        fail "$cmd exited nonzero: $(head -n 2 "$err" | tr '\n' ' ')"
        rm -f "$out" "$err"
        return
    fi

    local ok=1
    local marker
    for marker in "$@"; do
        if ! grep -Fq -- "$marker" "$out"; then
            printf '  FAIL: %s missing marker: %s\n' "$cmd" "$marker"
            ok=0
        fi
    done

    if grep -Eq 'Unknown command|Routed to|not implemented|placeholder|TODO|FIXME' "$out"; then
        printf '  FAIL: %s printed placeholder/fallback text\n' "$cmd"
        ok=0
    fi

    if [ "$ok" -eq 1 ]; then
        pass
    else
        tests_failed=$((tests_failed + 1))
    fi

    rm -f "$out" "$err"
}

assert_command_unknown() {
    local cmd="$1"
    local out err
    out="$(mktemp)"
    err="$(mktemp)"
    tests_run=$((tests_run + 1))

    if run_capture "$cmd" "$out" "$err"; then
        printf '  FAIL: %s unexpectedly succeeded\n' "$cmd"
        tests_failed=$((tests_failed + 1))
        rm -f "$out" "$err"
        return
    fi

    if grep -Fq -- "Unknown command" "$err"; then
        pass
    else
        printf '  FAIL: %s did not report Unknown command\n' "$cmd"
        tests_failed=$((tests_failed + 1))
    fi

    rm -f "$out" "$err"
}

assert_command_fails_with() {
    local cmd="$1"
    local marker="$2"
    local out err
    out="$(mktemp)"
    err="$(mktemp)"
    tests_run=$((tests_run + 1))

    if run_capture "$cmd" "$out" "$err"; then
        printf '  FAIL: %s unexpectedly succeeded\n' "$cmd"
        tests_failed=$((tests_failed + 1))
    elif grep -Fq -- "$marker" "$err" || grep -Fq -- "$marker" "$out"; then
        pass
    else
        printf '  FAIL: %s did not report: %s\n' "$cmd" "$marker"
        tests_failed=$((tests_failed + 1))
    fi

    rm -f "$out" "$err"
}

assert_command_excludes() {
    local cmd="$1"
    local forbidden="$2"
    local out err
    out="$(mktemp)"
    err="$(mktemp)"
    tests_run=$((tests_run + 1))

    if ! run_capture "$cmd" "$out" "$err"; then
        fail "$cmd exited nonzero: $(head -n 2 "$err" | tr '\n' ' ')"
    elif grep -Fq -- "$forbidden" "$out"; then
        fail "$cmd unexpectedly printed: $forbidden"
    else
        pass
    fi

    rm -f "$out" "$err"
}

is_public_command() {
    local cmd="$1"
    local name="${cmd%% *}"
    case "$name" in
			field|table|golden-threshold-table|tables|verify|reciprocal-square-selection|weighted-reference-profile|digit-partition|alignment-limit|three-tier|deficit-lattice|coherence-decomposition|cross-alignment|spectral-structure|spectral-power|spectral|align|decompose|survey|range|polar|div|equations|coherence|analytic|help|collision_table|spectrum|autocorrelation|phase-gate|bin-derangements|collision-characters|silent-primes|collision-fluctuation|collision-centering|centered-collision|collision-table|collision-periodic-table|collision-transform|residue-three-neutrality|neutrality-theorem|compatible-residue-channels|general-neutrality|primitive-character-cancellation|periodic-zeta-factorization|collision-boundary-recovery|active-collision-channel|collision-coordinate|finite-determination|reflection-identity|half-group|all-prime-collision-label|finite-spectral-quotient|finite-prefix-slice|boundary-bernoulli-factorization|boundary-conductor-ledger|finite-state-orbit-boundary|full-orbit-energy|quadratic-orbit-energy|subgroup-jacobi-expansion|prime-base-collision-energy|arithmetic-boundary-defect|carry-completed-carrier|terminal-collision-conductor-ledger|derangements|silent_primes|gate_width|fluctuation_sum|character_components|class_bias|class_means|centered_sum|mertens_growth|neutrality|neutrality_sweep|finite_det|mod3_means|gate|polarity_field|scale)
            return 0
            ;;
        ''|*[!0-9]*)
            return 1
            ;;
        *)
            return 0
            ;;
    esac
}

assert_all_try_it_commands_run() {
    local commands_file out err cmd

    if [ -z "$COMMAND_DOC_ROOT" ]; then
        return
    fi

    commands_file="$(mktemp)"
    out="$(mktemp)"
    err="$(mktemp)"

    if ! compgen -G "$COMMAND_DOC_ROOT/posts/*.md" >/dev/null &&
       ! compgen -G "$COMMAND_DOC_ROOT/posts/try-it-specs/*.md" >/dev/null; then
        rm -f "$commands_file" "$out" "$err"
        return
    fi

    awk '/\$ \.\/nfield/ {
        line=$0
        sub(/^.*\$ \.\/nfield /, "", line)
        sub(/#.*/, "", line)
        gsub(/[[:space:]]+$/, "", line)
        print line
    }' "$COMMAND_DOC_ROOT"/posts/*.md "$COMMAND_DOC_ROOT"/posts/try-it-specs/*.md | sort -u >"$commands_file"

    while IFS= read -r cmd; do
        [ -n "$cmd" ] || continue
        if ! is_public_command "$cmd"; then
            continue
        fi
        tests_run=$((tests_run + 1))
        if ! run_capture "$cmd" "$out" "$err"; then
            fail "$cmd exited nonzero: $(head -n 2 "$err" | tr '\n' ' ')"
            continue
        fi
        if grep -Eq 'Unknown command|Routed to|not implemented|placeholder|TODO|FIXME' "$out"; then
            fail "$cmd printed placeholder/fallback text"
            continue
        fi
        pass
    done <"$commands_file"

    rm -f "$commands_file" "$out" "$err"
}

